//! Request-format tests for the shared parser.
//!
//! The positives replay `request_vectors.txt`, generated byte-for-byte by the host
//! driver's Python encoder (`host/gen_request_vectors.py`) — so the two sides of
//! the wire are held compatible by tests on both. The negatives are hand-crafted
//! malformed buffers exercising the strict-parse rules; each is paired with a
//! well-formed twin that parses, so a refusal is attributable to the named defect
//! rather than to a parser that refuses everything.

use proofofseed_circuits::request::{parse_proof_request, Family, MAX_ITERS, MIN_ITERS};

const H: u32 = 0x8000_0000;

/// The golden vectors, as `name -> payload` (see the fixture header).
fn vectors() -> std::collections::HashMap<String, Vec<u8>> {
    include_str!("request_vectors.txt")
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .map(|l| {
            let (name, hex) = l.split_once(' ').expect("name and hex");
            let bytes = (0..hex.len())
                .step_by(2)
                .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("valid hex"))
                .collect();
            (name.to_string(), bytes)
        })
        .collect()
}

#[test]
fn golden_vectors_from_the_python_encoder_parse_as_intended() {
    let v = vectors();
    let case = |name: &str| parse_proof_request(&v[name], true).unwrap_or_else(|| panic!("{name} must parse"));

    let bare = case("bare");
    assert_eq!(bare.num_iters, 6);
    assert_eq!(bare.rounds, 2048, "default rounds");
    assert_eq!(bare.family, Family::Bip32Secp256k1, "default family");
    assert!(bare.path.is_none() && bare.index.is_none() && bare.chain_code.is_none());
    assert!(bare.binding.is_empty());

    let rounds = case("rounds-only");
    assert_eq!((rounds.num_iters, rounds.rounds), (6, 4));

    let eth = case("eth-parent-path");
    assert_eq!(eth.num_iters, 2);
    assert_eq!(eth.path.as_deref(), Some(&[H | 44, H | 60, H | 0][..]));

    let anchored = case("anchored-index-cc");
    assert_eq!(anchored.index, Some(H));
    let cc: [u8; 32] = core::array::from_fn(|i| i as u8);
    assert_eq!(anchored.chain_code, Some(cc));

    let bound = case("bound");
    assert_eq!((bound.num_iters, &bound.binding[..]), (8, &b"tx"[..]));

    let btc = case("bitcoin-p2wpkh-account");
    assert_eq!(btc.family, Family::Bip32Secp256k1);
    assert_eq!(btc.path.as_deref(), Some(&[H | 84, H | 0][..]));
    assert_eq!(btc.index, Some(H));
    let cc: [u8; 32] = core::array::from_fn(|i| 32 + i as u8);
    assert_eq!(btc.chain_code, Some(cc));
    assert_eq!(btc.binding, vec![0x11u8; 32]);

    let sol_fam = case("solana-family");
    assert_eq!(sol_fam.family, Family::Slip10Ed25519);
    assert!(sol_fam.path.is_none() && sol_fam.index.is_none());

    let sol = case("solana-account");
    assert_eq!(sol.family, Family::Slip10Ed25519);
    assert_eq!(sol.path.as_deref(), Some(&[H | 44, H | 501][..]));
    assert_eq!(sol.index, Some(H));
    let cc: [u8; 32] = core::array::from_fn(|i| 64 + i as u8);
    assert_eq!(sol.chain_code, Some(cc));
    assert_eq!(sol.binding, b"sol-tx");

    let ranged = case("ranged");
    assert_eq!((ranged.num_iters, ranged.range), (438, Some((0, 219))));

    let single = case("ranged-single");
    assert_eq!(single.range, Some((7, 8)), "a single-response range");
    assert_eq!(single.binding, b"tx", "binding precedes the range fields");

    let sol_ranged = case("solana-ranged");
    assert_eq!(sol_ranged.family, Family::Slip10Ed25519);
    assert_eq!(sol_ranged.range, Some((219, 438)));
    assert_eq!(sol_ranged.binding, b"sol-tx");

    // The encoder emits unknown family values on request (for tests like this one);
    // the parser must refuse them.
    assert!(
        parse_proof_request(&v["unknown-family"], true).is_none(),
        "an unknown family byte must refuse"
    );
}

#[test]
fn exec_requests_ignore_num_iters() {
    let v = vectors();
    let req = parse_proof_request(&v["bitcoin-p2wpkh-account"], false).expect("must parse");
    assert_eq!(req.num_iters, 0);
    assert_eq!(req.path.as_deref(), Some(&[H | 84, H | 0][..]), "other fields unaffected");
}

#[test]
fn num_iters_bounds_are_clamped() {
    let max = parse_proof_request(&[0xff, 0xff], true).expect("must parse");
    assert_eq!(max.num_iters, MAX_ITERS as usize);
    let min = parse_proof_request(&[0x00, 0x00], true).expect("must parse");
    assert_eq!(min.num_iters, MIN_ITERS as usize);
}

#[test]
fn strict_parse_refuses_each_named_defect() {
    // (name, well-formed twin, defective buffer): the twin parses, the defect refuses,
    // and the two differ only in the named respect.
    let cases: [(&str, Vec<u8>, Vec<u8>); 12] = [
        (
            "odd-length prefix (1 byte)",
            vec![0x00, 0x04],
            vec![0x00],
        ),
        (
            "odd-length prefix (3 bytes)",
            vec![0x00, 0x04, 0x08, 0x00],
            vec![0x00, 0x04, 0x08],
        ),
        (
            "unknown flag bit 0x80",
            vec![0x00, 0x04, 0x08, 0x00, 0x00],
            vec![0x00, 0x04, 0x08, 0x00, 0x80],
        ),
        (
            "reserved flag bit 0x08",
            vec![0x00, 0x04, 0x08, 0x00, 0x00],
            vec![0x00, 0x04, 0x08, 0x00, 0x08],
        ),
        (
            "family flag without its byte",
            vec![0x00, 0x04, 0x08, 0x00, 0x10, 0x00],
            vec![0x00, 0x04, 0x08, 0x00, 0x10],
        ),
        (
            "path declaring more components than it carries",
            vec![0x00, 0x04, 0x08, 0x00, 0x01, 0x01, 0x80, 0x00, 0x00, 0x2c],
            vec![0x00, 0x04, 0x08, 0x00, 0x01, 0x02, 0x80, 0x00, 0x00, 0x2c],
        ),
        (
            "binding declaring more bytes than it carries",
            vec![0x00, 0x04, 0x08, 0x00, 0x04, 0x02, 0x74, 0x78],
            vec![0x00, 0x04, 0x08, 0x00, 0x04, 0x03, 0x74, 0x78],
        ),
        (
            "undeclared trailing byte",
            vec![0x00, 0x04, 0x08, 0x00, 0x00],
            vec![0x00, 0x04, 0x08, 0x00, 0x00, 0xaa],
        ),
        (
            "range truncated to start alone",
            vec![0x00, 0x04, 0x08, 0x00, 0x20, 0x00, 0x00, 0x00, 0x02],
            vec![0x00, 0x04, 0x08, 0x00, 0x20, 0x00, 0x00],
        ),
        (
            "empty range (start == end)",
            vec![0x00, 0x04, 0x08, 0x00, 0x20, 0x00, 0x01, 0x00, 0x02],
            vec![0x00, 0x04, 0x08, 0x00, 0x20, 0x00, 0x01, 0x00, 0x01],
        ),
        (
            "inverted range (start > end)",
            vec![0x00, 0x04, 0x08, 0x00, 0x20, 0x00, 0x01, 0x00, 0x02],
            vec![0x00, 0x04, 0x08, 0x00, 0x20, 0x00, 0x02, 0x00, 0x01],
        ),
        (
            "range end beyond num_iters",
            vec![0x00, 0x04, 0x08, 0x00, 0x20, 0x00, 0x00, 0x00, 0x04],
            vec![0x00, 0x04, 0x08, 0x00, 0x20, 0x00, 0x00, 0x00, 0x05],
        ),
    ];
    for (defect, twin, bad) in cases {
        assert!(parse_proof_request(&twin, true).is_some(), "the {defect} twin must parse");
        assert!(parse_proof_request(&bad, true).is_none(), "{defect} must refuse");
    }
    // A truncated index+chain-code block refuses at every cut, and its twin parses.
    let mut anchored = vec![0x00, 0x04, 0x08, 0x00, 0x02, 0x80, 0x00, 0x00, 0x00];
    anchored.extend_from_slice(&[0u8; 32]);
    assert!(parse_proof_request(&anchored, true).is_some(), "the anchored twin must parse");
    for cut in [anchored.len() - 1, anchored.len() - 12, 6] {
        assert!(
            parse_proof_request(&anchored[..cut], true).is_none(),
            "an index+chain-code block truncated to {cut} bytes must refuse"
        );
    }
}

#[test]
fn range_bounds_check_uses_the_clamped_response_count() {
    // num_iters 0xffff clamps to MAX_ITERS; a range within the wire value but beyond
    // the clamp must refuse (the challenge sequence is MAX_ITERS long, not 0xffff).
    let ok = [0xff, 0xff, 0x08, 0x00, 0x20, 0x00, 0x00, 0x02, 0x00];
    let req = parse_proof_request(&ok, true).expect("a range within the clamp must parse");
    assert_eq!((req.num_iters, req.range), (MAX_ITERS as usize, Some((0, MAX_ITERS))));
    let beyond = [0xff, 0xff, 0x08, 0x00, 0x20, 0x00, 0x00, 0x02, 0x01];
    assert!(
        parse_proof_request(&beyond, true).is_none(),
        "a range end beyond the clamped count must refuse"
    );
    // Exec ignores num_iters, so only the range's internal order is checked there.
    assert!(
        parse_proof_request(&beyond, false).is_some(),
        "exec ignores num_iters and the range alike"
    );
}

#[test]
fn explicit_default_family_byte_is_accepted() {
    // family flag + explicit 0: a valid, non-canonical spelling of the default.
    let req = parse_proof_request(&[0x00, 0x04, 0x08, 0x00, 0x10, 0x00], true).expect("must parse");
    assert_eq!(req.family, Family::Bip32Secp256k1);
}
